carte.css:
body{background:#fff;color:#fff}
.sb{height:70px;display:flex;justify-content:space-between;align-items:center;padding:0 52px;font-weight:600;font-size:30px;background:#fff;color:#111}
.sb .dr{display:flex;align-items:center;gap:14px;font-size:24px}
.sig{display:flex;align-items:flex-end;gap:3px}.sig i{width:6px;background:#111;border-radius:1px}
.bat{width:52px;height:24px;border:2.5px solid #111;border-radius:6px;padding:2px;position:relative}
.bat::after{content:'';position:absolute;right:-7px;top:6px;width:4px;height:8px;background:#111;border-radius:0 2px 2px 0}
.bat i{display:block;width:12%;height:100%;background:#e11d48;border-radius:2px}
.hd{height:100px;background:#fff;display:flex;align-items:center;justify-content:space-between;padding:0 40px;color:#111}
.hd .ic{width:56px;height:56px;border-radius:50%;background:#eceff3;display:flex;align-items:center;justify-content:center;font-size:28px;color:#6b7280}
.logo{display:flex;align-items:center;gap:10px;font-weight:800;font-size:40px;letter-spacing:-.5px;color:#e11d48}
.logo .cr{font-size:40px}
.zone{background:#fff;padding:6px 22px 0}
.cartep{position:relative;height:820px;border-radius:34px;overflow:hidden;box-shadow:0 8px 30px rgba(0,0,0,.25)}
.photo{position:absolute;inset:0;
 background:
  radial-gradient(ellipse at 30% 15%,rgba(255,214,150,.55),transparent 55%),
  radial-gradient(ellipse at 50% 120%,rgba(0,0,0,.55),transparent 60%),
  repeating-linear-gradient(97deg,rgba(0,0,0,.06) 0 3px,transparent 3px 19px),
  repeating-linear-gradient(97deg,rgba(255,255,255,.04) 0 1px,transparent 1px 47px),
  linear-gradient(180deg,#8a5a36,#6b4226 60%,#4a2c18)}
.pile{position:absolute;left:250px;top:215px;transform-origin:top;width:540px;transform:rotate(-4deg)}
.bords{position:relative;height:330px}
.bords i{position:absolute;width:540px;height:12px;border-radius:2px;box-shadow:0 2px 2px rgba(0,0,0,.18)}
.dessus{position:absolute;left:-6px;top:-300px;width:552px;height:320px;background:#fffdf8;border-radius:3px;
 transform:perspective(900px) rotateX(48deg);transform-origin:bottom;box-shadow:0 -2px 6px rgba(0,0,0,.15);padding:46px 60px;overflow:hidden;
 background-image:repeating-linear-gradient(#fffdf8 0 37px,#c7d7ee 37px 39px)}
.dessus .mg{position:absolute;left:44px;top:0;bottom:0;width:2px;background:#f2a3a3}
.dessus span{display:block;height:5px;margin:16px 0 28px 10px;border-radius:3px;background:linear-gradient(90deg,#3b4b7a,#2d3a63);opacity:.55;filter:blur(.4px)}
.ck{position:absolute;font-size:46px;color:#d11;transform:rotate(-8deg)}.ck.x{color:#d11}
.ombre{position:absolute;left:230px;top:500px;width:600px;height:60px;background:rgba(0,0,0,.45);filter:blur(18px);border-radius:50%}
.tasse{position:absolute;left:810px;top:360px;width:150px;height:160px;border-radius:0 0 34px 34px;
 background:linear-gradient(90deg,#d9d4cc,#fdfbf7 35%,#e7e2da 70%,#b9b2a7);box-shadow:-18px 26px 30px rgba(0,0,0,.45)}
.tasse::before{content:'';position:absolute;top:-24px;left:0;width:150px;height:48px;border-radius:50%;background:radial-gradient(ellipse at 50% 55%,#3b2414 0 55%,#efeae2 57% 100%)}
.tasse::after{content:'';position:absolute;right:-48px;top:34px;width:56px;height:74px;border:16px solid #e2ddd4;border-left:none;border-radius:0 40px 40px 0}
.stylo{position:absolute;left:640px;top:170px;width:330px;height:20px;border-radius:10px;transform:rotate(38deg);
 background:linear-gradient(180deg,#ef4444,#b91c1c);box-shadow:6px 14px 14px rgba(0,0,0,.4)}
.stylo::before{content:'';position:absolute;right:-26px;top:3px;border-left:28px solid #f3d7b5;border-top:7px solid transparent;border-bottom:7px solid transparent}
.stylo::after{content:'';position:absolute;left:20px;top:-6px;width:110px;height:8px;background:#9b1c1c;border-radius:4px}
.pg{position:absolute;top:16px;left:16px;right:16px;display:flex;gap:8px}.pg i{flex:1;height:7px;border-radius:4px;background:rgba(255,255,255,.4)}.pg i:first-child{background:#fff}
.info{position:absolute;left:0;right:0;bottom:0;padding:120px 40px 30px;background:linear-gradient(transparent,rgba(0,0,0,.88) 45%)}
.nom{font-size:62px;font-weight:800;display:flex;align-items:center;gap:16px;text-shadow:0 2px 8px rgba(0,0,0,.4)}
.nom .age{font-weight:400}
.ver{width:42px;height:42px;border-radius:50%;background:#3b82f6;display:inline-flex;align-items:center;justify-content:center;font-size:26px}
.li{font-size:30px;margin-top:10px;opacity:.95}
.chips{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}
.chips span{background:rgba(255,255,255,.18);border:1.5px solid rgba(255,255,255,.35);padding:8px 20px;border-radius:999px;font-size:26px;font-weight:500}
.bio{font-size:28px;margin-top:18px;line-height:1.3;opacity:.95}
.act{height:150px;display:flex;justify-content:center;align-items:center;gap:40px}
.act span{border-radius:50%;background:#fff;box-shadow:0 6px 18px rgba(0,0,0,.18);display:flex;align-items:center;justify-content:center;font-weight:800}
.s1{width:80px;height:80px;font-size:36px;color:#f59e0b}.s2{width:116px;height:116px;font-size:58px;color:#ef4444}
.s3{width:80px;height:80px;font-size:38px;color:#3b82f6}.s4{width:116px;height:116px;font-size:56px;color:#10b981}
.wm{position:absolute;right:30px;bottom:12px;font-size:20px;color:#9ca3af;font-weight:600}
.act{height:140px}.home{height:44px;display:flex;justify-content:center;align-items:center}.home i{width:300px;height:10px;border-radius:5px;background:#111}.wm{bottom:58px}.actif{display:inline-flex;align-items:center;gap:10px;background:rgba(16,185,129,.25);border:1.5px solid rgba(16,185,129,.7);color:#d1fae5;font-size:24px;font-weight:600;padding:6px 16px;border-radius:999px;margin-bottom:12px}.actif i{width:14px;height:14px;border-radius:50%;background:#10b981}.notif{position:absolute;top:14px;left:22px;right:22px;z-index:10;background:#f7f5f2;border-radius:40px;box-shadow:0 18px 50px rgba(0,0,0,.35),0 0 0 1px rgba(0,0,0,.05);padding:22px 28px;display:flex;gap:22px;align-items:flex-start;color:#111}.notif .ap{flex:none;width:96px;height:96px;border-radius:24px;background:linear-gradient(160deg,#ff8a3d,#e8500f);display:flex;align-items:center;justify-content:center}.notif .tx{flex:1}.notif .l1{display:flex;justify-content:space-between;font-size:26px;color:#6b7280;font-weight:600}.notif .l1 b{color:#111;font-size:28px}.notif .t{font-size:33px;font-weight:800;margin-top:6px;line-height:1.22}.notif .m{font-size:28px;margin-top:8px;line-height:1.3;color:#222}.notif .m b{color:#e8500f;display:block;font-size:31px;margin-top:4px}.wm{display:none}.espace{height:150px;background:#fff}
